python3 << 'EOF'
from pptx import Presentation
from pptx.util import Emu

for path in ["brand/company-design-template.pptx", "Sprint 1.pptx"]:
    print(f"\n=== {path} ===")
    prs = Presentation(path)
    print(f"Slide size: {prs.slide_width} x {prs.slide_height} ({Emu(prs.slide_width).inches}in x {Emu(prs.slide_height).inches}in)")
    print(f"Layouts ({len(prs.slide_layouts)}):")
    for i, lay in enumerate(prs.slide_layouts):
        print(f"  [{i}] name={lay.name!r}")
        for ph in lay.placeholders:
            print(f"       ph idx={ph.placeholder_format.idx} type={ph.placeholder_format.type} name={ph.name!r}")
    print(f"Slides ({len(prs.slides)}):")
    for i, s in enumerate(prs.slides):
        print(f"  slide {i+1}: layout={s.slide_layout.name!r}")
        for ph in s.placeholders:
            txt = ph.text_frame.text if ph.has_text_frame else ""
            print(f"     ph idx={ph.placeholder_format.idx} name={ph.name!r} text={txt[:80]!r}")
        for sh in s.shapes:
            if not sh.is_placeholder:
                print(f"     shape name={sh.name!r} type={sh.shape_type}")
EOF
